// Builds tests/fixtures/sample.pdf by hand: a one-page PDF, Helvetica, one text
// object per line. Run with: npx tsx tests/fixtures/make-fixture-pdf.ts
import fs from "node:fs";
import path from "node:path";

export const FIXTURE_LINES = [
  "Tiny Fixture Paper on Citation Checking",
  "ABSTRACT",
  "We describe a small fixture document used to test PDF extraction. It has a",
  "few short paragraphs, headings in capital letters, and wrapped lines so that",
  "paragraph reconstruction can be exercised end to end.",
  "1 INTRODUCTION",
  "Citations generated by language models are often plausible but unsupported.",
  "Checking each one by hand is slow, so we automate the first step: fetching",
  "the cited paper and storing its text in retrievable chunks.",
  "The second paragraph of the introduction notes that hyphenated words like",
  "transfor-",
  "mer should be rejoined when a line break splits them.",
  "2 RESULTS",
  "The fixture contains exactly three headings and four body paragraphs.",
];

function escapePdfString(s: string) {
  return s.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}

export function buildPdf(lines: string[]): Buffer {
  let y = 750;
  const ops: string[] = [];
  for (const line of lines) {
    const heading = line === line.toUpperCase() || line === lines[0];
    if (heading) y -= 10; // extra space before headings
    ops.push(`BT /F1 ${heading ? 13 : 11} Tf 72 ${y} Td (${escapePdfString(line)}) Tj ET`);
    y -= 16;
  }
  const stream = ops.join("\n");

  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
    `<< /Length ${Buffer.byteLength(stream, "latin1")} >>\nstream\n${stream}\nendstream`,
    "<< /Title (Tiny Fixture Paper on Citation Checking) /Producer (hand-built fixture) >>",
  ];

  let out = "%PDF-1.4\n";
  const offsets: number[] = [];
  objects.forEach((body, i) => {
    offsets.push(Buffer.byteLength(out, "latin1"));
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xrefAt = Buffer.byteLength(out, "latin1");
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  for (const off of offsets) out += `${String(off).padStart(10, "0")} 00000 n \n`;
  out += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info 6 0 R >>\nstartxref\n${xrefAt}\n%%EOF\n`;
  return Buffer.from(out, "latin1");
}

if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(import.meta.filename)) {
  const file = path.join(import.meta.dirname, "sample.pdf");
  fs.writeFileSync(file, buildPdf(FIXTURE_LINES));
  console.log(`wrote ${file}`);
}
